<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_password_request_handler() { if ( ! sd_core_form_nonce( 'sd_lostpassword' ) ) { sd_core_auth_redirect( 'password-error' ); } if ( sd_core_rate_limited( 'lostpassword', 5 ) ) { sd_core_auth_redirect( 'rate-limited', wp_get_referer() ); } $login = sd_core_post_text( 'user_login' ); if ( $login ) { retrieve_password( $login ); } sd_core_auth_redirect( 'password-sent', wp_get_referer() ); }
add_action( 'admin_post_nopriv_sd_lostpassword', 'sd_core_password_request_handler' ); add_action( 'admin_post_sd_lostpassword', 'sd_core_password_request_handler' );
function sd_core_reset_handler() { if ( ! sd_core_form_nonce( 'sd_reset_password' ) ) { sd_core_auth_redirect( 'reset-error' ); } $key = isset( $_POST['key'] ) ? sanitize_text_field( wp_unslash( $_POST['key'] ) ) : ''; $login = isset( $_POST['login'] ) ? sanitize_text_field( wp_unslash( $_POST['login'] ) ) : ''; $password = isset( $_POST['pass1'] ) ? (string) wp_unslash( $_POST['pass1'] ) : ''; $confirm = isset( $_POST['pass2'] ) ? (string) wp_unslash( $_POST['pass2'] ) : ''; $user = check_password_reset_key( $key, $login ); if ( is_wp_error( $user ) || strlen( $password ) < 8 || ! hash_equals( $password, $confirm ) ) { sd_core_auth_redirect( 'reset-error', wp_get_referer() ); } reset_password( $user, $password ); sd_core_auth_redirect( 'reset-success', sd_core_page_url( 'login', '/' ) ); }
add_action( 'admin_post_nopriv_sd_reset_password', 'sd_core_reset_handler' ); add_action( 'admin_post_sd_reset_password', 'sd_core_reset_handler' );

function sd_core_custom_reset_message( $message, $key, $user_login, $user_data ) { $url = add_query_arg( array( 'key' => rawurlencode( $key ), 'login' => rawurlencode( $user_login ) ), sd_core_page_url( 'reset-password', '/reset-password/' ) ); return __( 'Someone requested a password reset for your account. If this was you, use the link below:', 'social-discovery-core' ) . "\r\n\r\n" . esc_url_raw( $url ) . "\r\n\r\n" . __( 'If you did not request this, you can ignore this email.', 'social-discovery-core' ); }
add_filter( 'retrieve_password_message', 'sd_core_custom_reset_message', 10, 4 );
